from pathlib import Path

cells = [
{"cell_type":"markdown","metadata":{},"source":["# Population Cortical Depth Profile CI/CV QC\n","\n","This notebook evaluates regional cortical depth profiles across the cohort using the mean profile, 95% confidence interval, standard deviation, and coefficient of variation. It processes one CSV at a time and does not clean, interpolate, delete, or overwrite profiles."]},
{"cell_type":"code","execution_count":None,"metadata":{},"outputs":[],"source":["from pathlib import Path\nimport re\nimport gc\nimport numpy as np\nimport pandas as pd\nimport matplotlib.pyplot as plt\n\nRESULTS_ROOT=Path('/mnt/newStor/paros/paros_WORK/xintong/results/column_analysis')\nQC_ROOT=Path('/mnt/newStor/paros/paros_WORK/xintong/results/column_quality_qc')\nQC_ROOT.mkdir(parents=True,exist_ok=True)\nPATTERN=re.compile(r'^(?P<subject>D\\d+)_(?P<hemi>lh|rh)_(?P<region>.+)_(?P<metric>md|fa|ad|rd)\\.csv$')\nDEPTHS=21\nprint('Reading:',RESULTS_ROOT)\nprint('Writing:',QC_ROOT)"]},
{"cell_type":"markdown","metadata":{},"source":["## 1. Regional CI/CV summaries\n\nFor each subject × hemisphere × region × metric, trajectories are summarized at every cortical depth. The 95% CI is calculated as `mean ± 1.96 × SD / sqrt(n)`, and CV is `SD / abs(mean)`."]},
{"cell_type":"code","execution_count":None,"metadata":{},"outputs":[],"source":["rows=[]\nfor profile_dir in sorted(RESULTS_ROOT.glob('D*/profiles_before_clean')):\n    for path in sorted(profile_dir.glob('*.csv')):\n        m=PATTERN.match(path.name)\n        if not m: continue\n        meta=m.groupdict()\n        base={**meta,'path':str(path)}\n        if path.stat().st_size==0:\n            rows.append({**base,'status':'empty','n_trajectories':0,'n_depths':0,'mean_value':np.nan,'mean_sd':np.nan,'mean_ci_width':np.nan,'mean_cv':np.nan})\n            continue\n        try:\n            a=np.loadtxt(path,delimiter=',',ndmin=2)\n            if a.shape[1] != DEPTHS:\n                rows.append({**base,'status':'unexpected_depth_count','n_trajectories':a.shape[0],'n_depths':a.shape[1],'mean_value':np.nan,'mean_sd':np.nan,'mean_ci_width':np.nan,'mean_cv':np.nan})\n            else:\n                finite=np.isfinite(a)\n                means=np.nanmean(np.where(finite,a,np.nan),axis=0)\n                sd=np.nanstd(np.where(finite,a,np.nan),axis=0,ddof=1)\n                n=np.sum(finite,axis=0)\n                ci_width=2*1.96*sd/np.sqrt(np.maximum(n,1))\n                cv=sd/np.abs(means)\n                rows.append({**base,'status':'valid','n_trajectories':a.shape[0],'n_depths':a.shape[1],'mean_value':float(np.nanmean(means)),'mean_sd':float(np.nanmean(sd)),'mean_ci_width':float(np.nanmean(ci_width)),'mean_cv':float(np.nanmean(cv))})\n            del a\n            gc.collect()\n        except Exception as exc:\n            rows.append({**base,'status':'unreadable','n_trajectories':0,'n_depths':0,'mean_value':np.nan,'mean_sd':np.nan,'mean_ci_width':np.nan,'mean_cv':np.nan,'error':str(exc)})\nsummary=pd.DataFrame(rows)\nsummary.to_csv(QC_ROOT/'regional_ci_cv_summary.csv',index=False)\nprint('Profiles:',len(summary),'Subjects:',summary.subject.nunique())\ndisplay(summary.head())"]},
{"cell_type":"markdown","metadata":{},"source":["## 2. Population summaries\n\nThese tables summarize profile precision and relative trajectory variability by subject, metric, hemisphere, and region."]},
{"cell_type":"code","execution_count":None,"metadata":{},"outputs":[],"source":["def aggregate(group):\n    return group.agg(n_profiles=('path','size'),n_valid_profiles=('status',lambda s:int((s=='valid').sum())),n_empty_profiles=('status',lambda s:int((s=='empty').sum())),mean_ci_width=('mean_ci_width','mean'),median_ci_width=('mean_ci_width','median'),mean_cv=('mean_cv','mean'),median_cv=('mean_cv','median'),mean_sd=('mean_sd','mean')).reset_index()\nsubject_summary=aggregate(summary.groupby('subject'))\nmetric_summary=aggregate(summary.groupby('metric'))\nhemisphere_summary=aggregate(summary.groupby(['subject','hemi','metric']))\nregion_summary=aggregate(summary.groupby(['subject','hemi','region','metric']))\nfor name,df in [('subject',subject_summary),('metric',metric_summary),('subject_hemisphere_metric',hemisphere_summary),('subject_hemisphere_region_metric',region_summary)]: df.to_csv(QC_ROOT/f'{name}_ci_cv_summary.csv',index=False)\ndisplay(subject_summary); display(metric_summary)"]},
{"cell_type":"markdown","metadata":{},"source":["## 3. Group-level regional rankings\n\nRegions are ranked by mean CV and mean 95% CI width across all available subjects and hemispheres. Lower values indicate more consistent trajectories or a more precise regional mean estimate."]},
{"cell_type":"code","execution_count":None,"metadata":{},"outputs":[],"source":["ranking=(summary[summary.status=='valid'].groupby(['metric','region'],as_index=False).agg(subjects=('subject','nunique'),profiles=('path','size'),mean_cv=('mean_cv','mean'),mean_ci_width=('mean_ci_width','mean'),mean_sd=('mean_sd','mean'),mean_value=('mean_value','mean')).sort_values(['metric','mean_cv']))\nranking.to_csv(QC_ROOT/'population_region_rankings.csv',index=False)\nfor metric in sorted(ranking.metric.unique()):\n    print(f'===== {metric.upper()} =====')\n    display(ranking[ranking.metric==metric].head(10))\n    display(ranking[ranking.metric==metric].sort_values('mean_cv',ascending=False).head(10))"]},
{"cell_type":"markdown","metadata":{},"source":["## 4. Population visualizations"]},
{"cell_type":"code","execution_count":None,"metadata":{},"outputs":[],"source":["fig,axes=plt.subplots(1,3,figsize=(18,5))\nvalid=summary[summary.status=='valid']\nvalid.boxplot(column='mean_cv',by='metric',ax=axes[0]); axes[0].set_title('Regional CV across the cohort'); axes[0].set_xlabel('Metric'); axes[0].set_ylabel('Mean CV'); plt.sca(axes[0]); plt.suptitle('')\nvalid.boxplot(column='mean_ci_width',by='metric',ax=axes[1]); axes[1].set_title('Regional 95% CI width across the cohort'); axes[1].set_xlabel('Metric'); axes[1].set_ylabel('Mean CI width'); plt.sca(axes[1]); plt.suptitle('')\nmetric_plot=valid.groupby(['subject','metric'],as_index=False).mean_cv.mean().reset_index() if False else valid.groupby(['subject','metric'],as_index=False)['mean_cv'].mean()\nfor metric,g in metric_plot.groupby('metric'): axes[2].plot(g.subject,g.mean_cv,marker='o',label=metric.upper())\naxes[2].set_title('Subject-level mean CV'); axes[2].set_xlabel('Subject'); axes[2].set_ylabel('Mean CV'); axes[2].tick_params(axis='x',rotation=90); axes[2].legend(); axes[2].grid(alpha=.25)\nfig.tight_layout(); fig.savefig(QC_ROOT/'population_ci_cv_overview.png',dpi=180); display(fig)"]},
]
